package com.vault.service;
import com.vault.dto.*;import com.vault.entity.*;import com.vault.repository.*;import com.vault.security.JwtService;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class AccountService{private final UserRepository users;private final ActivityLogRepository logs;private final PasswordEncoder encoder;private final JwtService jwt;public AccountService(UserRepository u,ActivityLogRepository l,PasswordEncoder e,JwtService j){users=u;logs=l;encoder=e;jwt=j;}
 @Transactional public Views.AuthView register(Requests.Register x){if(users.existsByEmail(x.email().toLowerCase()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");User u=users.save(new User(x.name().trim(),x.email().trim(),encoder.encode(x.password())));logs.save(new ActivityLog(u,null,"REGISTER","Created account",null));return new Views.AuthView(jwt.create(u.getEmail()),Views.UserView.from(u));}
 @Transactional public Views.AuthView login(Requests.Login x){User u=users.findByEmail(x.email().toLowerCase()).filter(a->encoder.matches(x.password(),a.getPasswordHash())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));logs.save(new ActivityLog(u,null,"LOGIN","Signed in",null));return new Views.AuthView(jwt.create(u.getEmail()),Views.UserView.from(u));}
 public User current(String email){return users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));}
 @Transactional public Views.UserView update(String email,Requests.Profile x){User u=current(email);u.setName(x.name().trim());return Views.UserView.from(u);}
 @Transactional public void password(String email,Requests.ChangePassword x){User u=current(email);if(!encoder.matches(x.currentPassword(),u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect");u.setPasswordHash(encoder.encode(x.newPassword()));}
}
